import Foundation
import Testing

@testable import TinyTitan

@Suite struct GGUFDequantTests {
    private struct Vector {
        let type: GGUFType
        let bytes: [UInt8]
        let expected: [UInt32]
    }

    /// Vectors are generated by `tools/gguf-ref-vectors.c` from ggml's own
    /// `dequantize_row_*`. The bytes are in the file, so the Swift decoder is
    /// fed exactly the block the reference decoded.
    private static func vectors() throws -> [Vector] {
        let url = try #require(
            Bundle.module.url(forResource: "GGUFDequantVectors", withExtension: "txt"))
        let data = try Data(contentsOf: url)
        let text = try #require(String(data: data, encoding: .utf8))
        var vectors: [Vector] = []
        for line in text.split(separator: "\n") where !line.hasPrefix("#") && !line.isEmpty {
            let parts = line.split(separator: "|", omittingEmptySubsequences: false)
            #expect(parts.count == 3)
            guard parts.count == 3 else { continue }
            let name = String(parts[0])
            let type = try #require(
                GGUFType.allCases.first { $0.name.uppercased() == name.uppercased() })
            vectors.append(
                Vector(
                    type: type,
                    bytes: try hexBytes(String(parts[1])),
                    expected: try hexWords(String(parts[2]))))
        }
        return vectors
    }

    private static func hexBytes(_ text: String) throws -> [UInt8] {
        var result: [UInt8] = []
        result.reserveCapacity(text.count / 2)
        var index = text.startIndex
        while index < text.endIndex {
            let next = text.index(index, offsetBy: 2)
            result.append(try #require(UInt8(text[index..<next], radix: 16)))
            index = next
        }
        return result
    }

    private static func hexWords(_ text: String) throws -> [UInt32] {
        var result: [UInt32] = []
        result.reserveCapacity(text.count / 8)
        var index = text.startIndex
        while index < text.endIndex {
            let next = text.index(index, offsetBy: 8)
            result.append(try #require(UInt32(text[index..<next], radix: 16)))
            index = next
        }
        return result
    }

    /// Bit equality, not approximate equality: these decodes are exact
    /// arithmetic on exactly representable scales, so any difference is a bug in
    /// the port rather than floating-point noise.
    @Test func matchesGGMLReferenceBitForBit() throws {
        let vectors = try Self.vectors()
        #expect(vectors.count == 7, "fixture should carry seven block types")
        #expect(
            Set(vectors.map(\.type.name))
                == ["Q6_K", "Q8_0", "Q2_0", "IQ4_NL", "IQ4_XS", "IQ2_S", "IQ3_XXS"])
        for vector in vectors {
            let got = try GGUFDequant.decode(type: vector.type, bytes: vector.bytes)
            #expect(
                got.count == vector.expected.count,
                "\(vector.type.name) decoded \(got.count) values, expected \(vector.expected.count)"
            )
            guard got.count == vector.expected.count else { continue }
            for index in 0..<got.count where got[index].bitPattern != vector.expected[index] {
                Issue.record(
                    "\(vector.type.name)[\(index)] = 0x\(String(got[index].bitPattern, radix: 16)), expected 0x\(String(vector.expected[index], radix: 16))"
                )
                break
            }
        }
    }

    /// The fixture's first block has one scale and the second another, so a
    /// decoder that reused the first block's scale fails the second half.
    @Test func decodesEveryBlockWithItsOwnScale() throws {
        let vectors = try Self.vectors()
        for vector in vectors where vector.type.blockSize > 1 {
            let values = try GGUFDequant.decode(type: vector.type, bytes: vector.bytes)
            let half = values.count / 2
            #expect(
                values[0] != values[half],
                "\(vector.type.name) block 1 repeated block 0's scale")
        }
    }

    @Test func refusesBlockTypesItDoesNotDecode() throws {
        for (type, bytes) in [(GGUFType.q4K, 144), (.q5K, 176)] {
            #expect(throws: GGUFDequantError.unsupportedType(type.name)) {
                try GGUFDequant.decode(type: type, bytes: [UInt8](repeating: 0, count: bytes))
            }
        }
    }

    @Test func refusesAByteCountThatIsNotABlock() throws {
        #expect(
            throws: GGUFDequantError.byteCountNotABlockMultiple(
                type: "IQ4_NL", bytes: 17, blockBytes: 18)
        ) {
            try GGUFDequant.decode(type: .iq4NL, bytes: [UInt8](repeating: 0, count: 17))
        }
    }

    @Test func decodesTheScalarTypes() throws {
        // 1.0 and -2.0 in each scalar wire form, little-endian.
        let f32 = try GGUFDequant.decode(
            type: .f32,
            bytes: [
                0x00, 0x00, 0x80, 0x3F, 0x00, 0x00, 0x00, 0xC0,
            ])
        #expect(f32 == [1.0, -2.0])
        let f16 = try GGUFDequant.decode(type: .f16, bytes: [0x00, 0x3C, 0x00, 0xC0])
        #expect(f16 == [1.0, -2.0])
        let bf16 = try GGUFDequant.decode(type: .bf16, bytes: [0x80, 0x3F, 0x00, 0xC0])
        #expect(bf16 == [1.0, -2.0])
    }
}
